  OvStoragePlugin_Str root;
  OvStoragePlugin_Optional_Str display_name;
  OvStoragePlugin_Str layer_kind;
  OvStoragePlugin_Optional_ConnectionId connection_id;
  OvStoragePlugin_Capabilities capabilities;
  OvStoragePlugin_RangeReadStrategy range_read_strategy;
  OvStoragePlugin_RouteSource source;
  bool visible;
  OvStoragePlugin_AddressVisibility visibility;
  OvStoragePlugin_Optional_AliasState alias_state;
  OvStoragePlugin_Optional_Bytes icon;
  OvStoragePlugin_UserMetadata user_metadata;
