  OvStoragePlugin_LayerStatFn stat;
  OvStoragePlugin_LayerReadFn read;
  OvStoragePlugin_LayerWriteFn write;
  OvStoragePlugin_LayerWriteFn write_stream;
  OvStoragePlugin_LayerWriteFn write_redirect;
  OvStoragePlugin_LayerContinueWriteFn continue_write;
  OvStoragePlugin_LayerDeleteFn delete_;
  OvStoragePlugin_LayerCopyFn copy;
  OvStoragePlugin_LayerRenameFn rename;
  OvStoragePlugin_LayerUpdateMetadataFn update_metadata;
  OvStoragePlugin_LayerCheckAccessFn check_access;
  OvStoragePlugin_LayerReadFn materialize;
  OvStoragePlugin_LayerListFn list;
  OvStoragePlugin_LayerListVersionsFn list_versions;
  OvStoragePlugin_LayerReadFn get_latest_version;
  OvStoragePlugin_LayerWatchDirectoryFn watch_directory;
  OvStoragePlugin_LayerCreateDirectoryFn create_directory;
  OvStoragePlugin_LayerDeleteDirectoryFn delete_directory;
  /**
   * Connection management.
   */
  OvStoragePlugin_LayerConnectionOpFn probe;
  OvStoragePlugin_LayerConnectionOpFn add_connection;
  OvStoragePlugin_LayerRemoveConnectionFn remove_connection;
  OvStoragePlugin_LayerListConnectionsFn list_connections;
  OvStoragePlugin_LayerUpdateCredentialsFn update_connection_credentials;
  OvStoragePlugin_LayerUpdateAttributesFn update_connection_attributes;
  OvStoragePlugin_LayerAuthenticateFn authenticate_connection;
